// Planet rendering: a cube-sphere quadtree whose patches are generated by web
// workers and swapped in seamlessly, so one system covers everything from a
// dot in the sky down to the ground under your feet.
import * as THREE from 'three';
import { FACES, patchDir, patchIndices } from './cubesphere.js';
import { smoothstep } from './noise.js';
import { terrainVS, terrainFS, atmoVS, atmoFS, uvVS, ringFS } from './shaders.js';

const MAX_LEVEL = 11;
const SPLIT = 1.4;
// The first few levels split from much farther out so a world seen from orbit
// has a smooth limb and crisp continents; this costs only a few dozen patches.
const COARSE_SPLIT = [7, 3.6, 2.4];
const tmp = [0, 0, 0];

class Node {
  constructor(planet, face, level, ix, iy) {
    this.planet = planet; this.face = face; this.level = level; this.ix = ix; this.iy = iy;
    const span = 2 / (1 << level);
    patchDir(FACES[face], -1 + (ix + 0.5) * span, -1 + (iy + 0.5) * span, tmp);
    const R = planet.def.radius;
    this.dir = new THREE.Vector3(tmp[0], tmp[1], tmp[2]);
    this.center = this.dir.clone().multiplyScalar(R);
    this.size = (R * Math.PI) / 2 / (1 << level);
    this.ang = (this.size * 0.75) / R;
    this.mesh = null; this.children = null; this.requested = false; this.dead = false;
  }
}

export class TerrainManager {
  constructor(workerCount = 2) {
    this.index = new THREE.BufferAttribute(patchIndices(), 1);
    this.workers = [];
    this.jobs = new Map();
    this.nextId = 1;
    this.wanted = [];
    this.inflight = 0;
    this.maxInflight = workerCount * 3;
    for (let i = 0; i < workerCount; i++) {
      const w = new Worker(new URL('./terrainWorker.js', import.meta.url), { type: 'module' });
      w.onmessage = (e) => this.onPatch(e.data);
      w.onerror = (e) => console.error('terrain worker error', e.message || e);
      this.workers.push(w);
    }
  }

  want(node, priority) {
    if (!node.requested) this.wanted.push({ node, priority });
  }

  // Dispatch the most urgent requests gathered during this frame's traversal.
  pump() {
    const w = this.wanted;
    if (w.length && this.inflight < this.maxInflight) {
      w.sort((a, b) => a.priority - b.priority);
      for (let i = 0; i < w.length && this.inflight < this.maxInflight; i++) {
        const node = w[i].node;
        if (node.requested || node.dead) continue;
        node.requested = true;
        const id = this.nextId++;
        this.jobs.set(id, node);
        this.inflight++;
        this.workers[id % this.workers.length].postMessage({
          id, planet: node.planet.index, face: node.face, level: node.level, ix: node.ix, iy: node.iy, maxLevel: MAX_LEVEL,
        });
      }
    }
    this.pending = w.length + this.inflight;
    w.length = 0;
  }

  onPatch(data) {
    const node = this.jobs.get(data.id);
    this.jobs.delete(data.id);
    this.inflight--;
    if (!node || node.dead) return;
    const g = new THREE.BufferGeometry();
    g.setIndex(this.index);
    g.setAttribute('position', new THREE.BufferAttribute(data.pos, 3));
    g.setAttribute('normal', new THREE.BufferAttribute(data.nrm, 3));
    g.setAttribute('aColor', new THREE.BufferAttribute(data.col, 3));
    g.setAttribute('aAux', new THREE.BufferAttribute(data.aux, 3));
    g.setAttribute('aDpos', new THREE.BufferAttribute(data.dps, 3));
    g.boundingSphere = new THREE.Sphere(new THREE.Vector3(), data.radius);
    const mesh = new THREE.Mesh(g, node.planet.material);
    mesh.position.set(data.center[0], data.center[1], data.center[2]);
    mesh.matrixAutoUpdate = false;
    mesh.updateMatrix();
    mesh.visible = false;
    node.planet.group.add(mesh);
    node.mesh = mesh;
    node.center.copy(mesh.position);
  }
}

export class Planet {
  constructor(def, index, manager, detailTex, scene) {
    this.def = def; this.index = index; this.manager = manager;
    this.pos = new THREE.Vector3(def.pos[0], def.pos[1], def.pos[2]);
    this.sunDir = new THREE.Vector3(def.sunDir[0], def.sunDir[1], def.sunDir[2]);
    this.group = new THREE.Group();
    this.group.matrixAutoUpdate = true;
    scene.add(this.group);
    this.cam = new THREE.Vector3();
    this.camDir = new THREE.Vector3();
    this.missing = 0;

    const a = def.atmo;
    this.uniforms = {
      uDetail: { value: detailTex },
      uCenter: { value: new THREE.Vector3() },
      uSunDir: { value: this.sunDir },
      uScatter: { value: new THREE.Vector3(...a.scatter) },
      uSunset: { value: new THREE.Vector3(...a.sunset) },
      uGlowColor: { value: new THREE.Vector3(...def.glow) },
      uFog: { value: 0 }, uSpace: { value: 1 }, uTime: { value: 0 }, uCamSunElev: { value: 1 },
      uR: { value: def.radius }, uRa: { value: def.radius + a.height * 8 }, uH: { value: a.height },
      uDensity: { value: a.density },
    };
    this.material = new THREE.ShaderMaterial({ vertexShader: terrainVS, fragmentShader: terrainFS, uniforms: this.uniforms });

    const shell = new THREE.Mesh(
      new THREE.SphereGeometry(1, 64, 40),
      new THREE.ShaderMaterial({
        vertexShader: atmoVS, fragmentShader: atmoFS, uniforms: this.uniforms,
        side: THREE.BackSide, transparent: true, depthWrite: false,
      }),
    );
    shell.scale.setScalar((def.radius + a.height * 8) * 1.03);
    shell.frustumCulled = false;
    this.group.add(shell);

    if (def.rings) {
      const ring = new THREE.Mesh(
        new THREE.RingGeometry(1.35, 2.4, 96, 1),
        new THREE.ShaderMaterial({
          vertexShader: uvVS, fragmentShader: ringFS, uniforms: this.uniforms,
          side: THREE.DoubleSide, transparent: true, depthWrite: false,
        }),
      );
      ring.scale.setScalar(def.radius);
      ring.rotation.set(1.25, 0.35, 0);
      ring.frustumCulled = false;
      this.group.add(ring);
    }

    this.roots = FACES.map((_, f) => new Node(this, f, 0, 0, 0));
  }

  // `playerPos` is the floating origin: everything is drawn relative to it so
  // the GPU only ever sees small, precise numbers near the player.
  update(playerPos, time) {
    const def = this.def;
    this.group.position.copy(this.pos).sub(playerPos);
    this.cam.copy(playerPos).sub(this.pos);
    const camDist = this.cam.length();
    this.camDir.copy(this.cam).divideScalar(camDist || 1);
    const alt = camDist - def.radius;
    const u = this.uniforms, H = def.atmo.height;
    u.uCenter.value.copy(this.group.position);
    u.uTime.value = time;
    u.uSpace.value = smoothstep(H * 1.5, H * 7, alt);
    u.uFog.value = (def.atmo.density / 9000) * Math.exp(-Math.max(alt, 0) / H);
    u.uCamSunElev.value = this.camDir.dot(this.sunDir);

    const rMin = def.radius - 700;
    this.horizon = Math.acos(Math.min(1, rMin / camDist)) + Math.acos(rMin / (def.radius + def.maxH));
    this.missing = 0;
    for (const root of this.roots) this.visit(root);
  }

  visit(node) {
    const dist = node.center.distanceTo(this.cam);
    // Hysteresis on merge avoids thrashing patches at a LOD boundary.
    if (node.level < MAX_LEVEL && dist < node.size * (COARSE_SPLIT[node.level] || SPLIT) * (node.children ? 1.2 : 1)) {
      if (!node.children) {
        const l = node.level + 1, x = node.ix * 2, y = node.iy * 2;
        node.children = [new Node(this, node.face, l, x, y), new Node(this, node.face, l, x + 1, y),
          new Node(this, node.face, l, x, y + 1), new Node(this, node.face, l, x + 1, y + 1)];
      }
      let ready = true;
      for (const c of node.children) {
        if (!c.mesh) { ready = false; this.missing++; this.manager.want(c, c.center.distanceTo(this.cam) / c.size + c.level * 0.01); }
      }
      if (ready) {
        if (node.mesh) node.mesh.visible = false;
        for (const c of node.children) this.visit(c);
        return;
      }
      for (const c of node.children) this.hide(c);
      this.show(node, dist);
    } else {
      if (node.children) { for (const c of node.children) this.dispose(c); node.children = null; }
      this.show(node, dist);
    }
  }

  show(node, dist) {
    if (!node.mesh) { this.missing++; this.manager.want(node, dist / node.size); return; }
    node.mesh.visible = Math.acos(Math.min(1, node.dir.dot(this.camDir))) - node.ang < this.horizon;
  }

  hide(node) {
    if (node.mesh) node.mesh.visible = false;
    if (node.children) for (const c of node.children) this.hide(c);
  }

  dispose(node) {
    node.dead = true;
    if (node.mesh) {
      this.group.remove(node.mesh);
      node.mesh.geometry.setIndex(null); // the index buffer is shared; keep it alive
      node.mesh.geometry.dispose();
      node.mesh = null;
    }
    if (node.children) for (const c of node.children) this.dispose(c);
  }
}
